"""Write nominal_calls.json.gz, the nominal surface of the configurations at one commit.

For every surface of SURFACES (configuration module, sample type, era) the code is generated
without shifts and reduced to what a build computes: per scope the producer calls
(tests/helpers.generated_calls) and the output columns. tests/test_nominal_freeze.py compares
the code generated by the checkout with this file, apart from the changes it lists.

Run from the CROWN root in the test environment (scripts/setup_tests.sh), at the commit whose
nominal is to be frozen:

    python analysis_configurations/bbtautau/tests/fixtures/make_nominal_calls_fixture.py [workers]

The file holds each distinct call and column once, and the surfaces as indices into these lists.
"""
import concurrent.futures
import gzip
import json
import subprocess
import sys
from pathlib import Path

from analysis_configurations.bbtautau.constants import ERAS_RUN2, SCOPES
from analysis_configurations.bbtautau.tests.helpers import generate_code, generated_calls

import analysis_configurations.bbtautau.sm_config as sm_config

HERE = Path(__file__).resolve().parent
OUTPUT = HERE / "nominal_calls.json.gz"
TAU_SCOPES = ("et", "mt", "tt")


def surfaces():
    """(module, sample, era, scopes) of every frozen surface: each sample type of sm_config in
    every Run-2 era, a selection of the b-tag efficiency and tau-ID measurement configurations,
    and the NMSSM configuration on its legacy Run-2 and its Run-3 inputs."""
    result = []
    for era in ERAS_RUN2:
        for sample in sm_config.AVAILABLE_SAMPLES:
            scopes = TAU_SCOPES if sample == "embedding" else tuple(SCOPES)
            result.append(("sm_config", sample, era, scopes))
        for sample in ("ttbar", "dyjets", "diboson"):
            result.append(("sm_btag_efficiency_config", sample, era, tuple(SCOPES)))
        for sample in ("data", "dyjets", "diboson", "embedding"):
            result.append(("sm_tau_id_measurement_config", sample, era, ("mt", "mm")))
    result += [
        ("nmssm_config", "ttbar", "2018", tuple(SCOPES)),
        ("nmssm_config", "data", "2018", tuple(SCOPES)),
        ("nmssm_config", "ttbar", "2022postEE", tuple(SCOPES)),
        ("nmssm_config", "dyjets_amcatnlo_ll", "2022postEE", tuple(SCOPES)),
        ("nmssm_config", "ttbar", "2024", tuple(SCOPES)),
        ("nmssm_config", "diboson", "2024", tuple(SCOPES)),
        ("nmssm_config", "data", "2024", tuple(SCOPES)),
    ]
    return result


def surface_key(module, sample, era):
    return f"{module}/{sample}/{era}"


def nominal_surface(surface):
    """The calls and the output columns of one surface per scope."""
    module, sample, era, scopes = surface
    generated = generate_code(module, sample, era=era, scopes=scopes)
    return {
        "calls": generated_calls(generated),
        "outputs": {scope: sorted(names) for scope, names in generated.outputs.items()},
    }


def main():
    workers = int(sys.argv[1]) if len(sys.argv) > 1 else 8
    todo = surfaces()
    with concurrent.futures.ThreadPoolExecutor(workers) as pool:  # the work runs in subprocesses
        results = list(pool.map(nominal_surface, todo))
    tables = {"calls": {}, "outputs": {}}
    content = {}
    for (module, sample, era, scopes), result in zip(todo, results):
        content[surface_key(module, sample, era)] = {
            kind: {
                scope: [tables[kind].setdefault(item, len(tables[kind])) for item in items]
                for scope, items in result[kind].items()
            }
            for kind in tables
        }
    commit = subprocess.check_output(
        ["git", "-C", str(HERE), "rev-parse", "HEAD"], text=True
    ).strip()
    payload = {
        "commit": commit,
        "calls": list(tables["calls"]),
        "outputs": list(tables["outputs"]),
        "surfaces": content,
    }
    with gzip.GzipFile(OUTPUT, "wb", mtime=0) as handle:
        handle.write(json.dumps(payload, sort_keys=True).encode())
    print(f"{len(content)} surfaces, {len(payload['calls'])} calls, "
          f"{len(payload['outputs'])} columns -> {OUTPUT}")


if __name__ == "__main__":
    main()
